              for (let j = 0; j < 6; j++) { const a = f.facing + rand(-0.38, 0.38), s = rand(300, 700); m.particle(f.x, f.y, { color: pick(['#ff5a1a', '#ffb02a', '#ffe07a']), life: 0.6, size: 6, vx: Math.cos(a) * s, vy: Math.sin(a) * s }); }
