              if (!caught) { caught = e; if (m.applyHit(f, e, { dmg: iai ? 9 : 4, kb: iai ? 230 : 0, kg: iai ? 6 : 0, noKnock: !iai, tag: 'C' }) && !iai) e.addStatus('stun', 2); }
