for (const id of SPELL_IDS) COMMANDS['sp_' + id] = { name: `${SPELLS[id].name}!`, icon: SPELLS[id].icon, spell: true, spellUse: id,
  desc: `Phép bổ trợ: ${SPELLS[id].desc} (hồi ${SPELLS[id].cd}s)`, ai: () => false };


