        // gặp Borg: bị áp sát thì đứng lên ngọn côn gồng 3s thả diều
        if (t.weaponId === 'nam_tay' && d < 100 && can('C')) { f.ws.holdWant = 3; return { k: 'C', cast: escapeAngle(f, t, m) }; }
