      const push = min - d, nx = (b.x - a.x) / d, ny = (b.y - a.y) / d;
      if (this.arena.inside(a.x - nx * push * ka, a.y - ny * push * ka, 2)) { a.x -= nx * push * ka; a.y -= ny * push * ka; }
