      if (p.home && p.home.alive) { const w = Math.atan2(p.home.y - p.y, p.home.x - p.x); p.ang += clamp(angDiff(p.ang, w), -p.turn * dt, p.turn * dt); p.vx = Math.cos(p.ang) * p.speed; p.vy = Math.sin(p.ang) * p.speed; }
